"""Build the approval-only KREUL privacy draft; never publish site content.

Run with the bundled documents Python. The dated text is an approval artifact,
not a production setting, legal opinion, or automatic compliance guarantee.
No merchant identity, verification token, customer data, or secrets are embedded.
"""
from pathlib import Path
from docx import Document
from docx.shared import Cm, Pt, RGBColor
from docx.oxml import OxmlElement
from docx.oxml.ns import qn

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / 'outputs/privacy-policy-2026-10-11/KREUL_политика_конфиденциальности_на_утверждение.docx'


def build():
    doc = Document()
    sec = doc.sections[0]
    sec.page_width, sec.page_height = Cm(21), Cm(29.7)
    sec.top_margin, sec.bottom_margin = Cm(1.9), Cm(1.8)
    sec.left_margin, sec.right_margin = Cm(2.1), Cm(2.1)
    for name in ['Normal', 'Title', 'Subtitle', 'Heading 1', 'Heading 2']:
        st = doc.styles[name]
        st.font.name = 'Arial'
        st.font.color.rgb = RGBColor(0, 0, 0)
    # Some bundled base templates add a coloured title border. Legal drafts
    # use plain black headings and no decorative paragraph rules.
    for st in doc.styles:
        for border in list(st.element.iter(qn('w:pBdr'))):
            border.getparent().remove(border)
    normal = doc.styles['Normal']
    normal.font.size = Pt(11)
    normal.paragraph_format.line_spacing = 1.12
    normal.paragraph_format.space_after = Pt(7)
    doc.styles['Title'].font.size = Pt(24)
    doc.styles['Heading 1'].font.size = Pt(16)
    doc.styles['Heading 2'].font.size = Pt(12)
    for name in ['Heading 1', 'Heading 2']:
        doc.styles[name].paragraph_format.space_before = Pt(10)
        doc.styles[name].paragraph_format.space_after = Pt(6)
    header = sec.header.paragraphs[0]
    header.text = 'KREUL • Проєкт для погодження • 11.10.2026'
    header.style = 'Normal'
    header.runs[0].font.size = Pt(9)
    footer = sec.footer.paragraphs[0]
    footer.alignment = 2
    footer.add_run('Сторінка ')
    fld = OxmlElement('w:fldSimple'); fld.set(qn('w:instr'), 'PAGE')
    footer._p.append(fld)
    doc.core_properties.title = 'Політика конфіденційності KREUL — проєкт для погодження'
    doc.core_properties.subject = 'Approval-only draft, not published'
    doc.core_properties.author = 'KREUL'

    def p(text): doc.add_paragraph(text)
    def h(text): doc.add_heading(text, level=2)
    def page(title): doc.add_page_break(); doc.add_heading(title, level=1)

    doc.add_paragraph('Политика конфиденциальности KREUL', 'Title')
    doc.add_paragraph('На утверждение владельцу • версия 0.1 • 11 октября 2026', 'Subtitle')
    p('Страница для владельца — не публиковать. Далее следует украинский проект для покупателей. Документ не опубликован на сайте и не является юридическим заключением. Поля в квадратных скобках нужно заполнить, а текст сверить с фактическими процессами магазина и юристом.')
    h('Что уже сделано и что ещё не включено')
    p('Дополнительное подтверждение Search Console установлено для того же текущего аккаунта владельца. Новый модуль согласия и электронной торговли остаётся выключенным. Существующий счётчик GA4 продолжает работать по прежней конфигурации: обещание «аналитика только после согласия» пока нельзя публиковать как описание текущего сайта.')
    h('Решения перед утверждением')
    for text in [
        'Указать продавца и владельца данных: полное имя ФОП или юридического лица, почтовый адрес, регистрационные реквизиты и контакт для обращений.',
        'Подтвердить получателей и операции: перевозчики, способы оплаты, фискализация, хостинг, бухгалтерия, рассылки и доступ сотрудников. Активный плагин сам по себе не доказывает передачу данных.',
        'Утвердить сроки отдельно для заказов, обращений, журналов и резервных копий. Бухгалтерские сроки определить с бухгалтером и юристом, а не переносить на всю аналитику.',
        'Выбрать срок событий GA4: 2 или 14 месяцев. Для сезонного анализа предлагается 14 месяцев; это предложение, настройка не изменялась. Отдельно решить, продлевать ли срок идентификатора при новой активности. Агрегированные отчёты этим лимитом не ограничиваются.',
        'Подтвердить cookie выбора аналитики на 180 дней. Проверить реальные сроки cookies GA4, корзины и кабинета; пока они не инвентаризированы полностью.',
        'Проверить все рекламные и аналитические подключения в сети до согласия, после согласия и после отказа. Не включать рекламные функции под видом согласия на статистику.'
    ]: doc.add_paragraph(text, 'List Bullet')
    h('Условие публикации')
    p('Сначала реквизиты и утверждённый текст, затем отдельное разрешение на публикацию и настройку согласия, после этого проверка на сайте. Если целевые условия не выполнены, соответствующие обещания нужно изменить. Продажи в рознице и опте не дают разрешения на рекламные рассылки.')

    page('Політика конфіденційності')
    p('Проєкт для погодження. Дата набуття чинності: [ВКАЗАТИ ПІСЛЯ ЗАТВЕРДЖЕННЯ]. Ця редакція описує цільову модель після налаштування згоди; до виконання умов погодження її не слід публікувати.')
    h('Хто відповідає за дані')
    p('Сайт https://kreul.com.ua/ працює під назвою «Лавка Художника / KREUL». Володілець персональних даних і продавець: [ПОВНЕ НАЙМЕНУВАННЯ ФОП АБО ЮРИДИЧНОЇ ОСОБИ]. Адреса: [АДРЕСА]. Реєстраційні відомості: [РЕКВІЗИТИ]. Контакт з питань персональних даних: [EMAIL]. Назва магазину не замінює ці відомості.')
    h('Для чого потрібні дані')
    p('Ми використовуємо необхідні дані для приймання та виконання замовлень, доставки, зв’язку щодо покупки, роботи особистого кабінету, повернень і ведення обов’язкових облікових документів. Окрема добровільна аналітика допомагає оцінювати джерела відвідувань і зручність каталогу. Рекламні повідомлення потребують окремо погодженого порядку.')
    h('Які відомості надає покупець')
    p('Під час замовлення або звернення ви можете надати ім’я, телефон, email, адресу чи пункт доставки, склад покупки та коментар. Для оптового обслуговування можуть знадобитися реквізити організації й контактної особи. Не просимо в коментарях паролі, повні реквізити картки, документи особи чи інші відомості, не потрібні для покупки.')
    p('У магазині зберігаються відомості про товари, кількість, суму, валюту, статус замовлення, доставки та оплати. Замовлення, його статус і підтверджений платіж — різні записи; аналітичний показник покупки не є банківською випискою.')
    h('Технічні дані та статистика')
